double squaredDistance(const Tree& tree, const Point3d& p) {
    // Initialize the squared distance to infinity
    double squared_dist = std::numeric_limits<double>::max();

    // Iterate over all triangles in the AABB tree
    for (const auto& triangle : tree.primitives()) {
        // Compute the squared distance from the query point to the triangle
        double dist = CGAL::squared_distance(p, triangle);

        // Update the minimum squared distance found so far
        squared_dist = std::min(squared_dist, dist);
    }

    // Return the minimum squared distance found
    return squared_dist;
